CREATE POLICY "event_ledger_web_mcp_retrieval_insert" ON "event_ledger" AS PERMISSIVE FOR INSERT TO "attention_web_runtime" WITH CHECK ("event_ledger"."account_id" = NULLIF(current_setting('app.account_id', true), '')::uuid AND "event_ledger"."event_type" = 'mcp_retrieval' AND "event_ledger"."scope" = 'public' AND "event_ledger"."content_id" IS NOT NULL AND "event_ledger"."anonymous_session_id" IS NULL AND "event_ledger"."request_id" IS NOT NULL AND "event_ledger"."dedupe_key" IS NOT NULL AND EXISTS (SELECT 1 FROM public_contents_current AS visible_content WHERE visible_content.id = "event_ledger"."content_id"));